import { type CSSProperties, type HTMLAttributes } from "react";
import { mergeClasses } from "./classes";
import {
  BalsaThemeContext,
  useResolvedThemeProps,
} from "./theme-context";
import type { ThemeInput } from "./theme";
import type { SemanticColor } from "./types";

export type SpinnerSize = "xs" | "sm" | "md" | "lg" | "xl";
export type SpinnerSpeed = "slow" | "normal" | "fast";
export type SpinnerLabelPosition = "hidden" | "right" | "bottom";

export interface SpinnerProps extends HTMLAttributes<HTMLSpanElement> {
  label?: string;
  labelPosition?: SpinnerLabelPosition;
  color?: SemanticColor;
  size?: SpinnerSize;
  speed?: SpinnerSpeed;
  theme?: ThemeInput;
}

const colorClasses: Readonly<Record<SemanticColor, string>> = {
  primary: "text-balsa-primary",
  secondary: "text-balsa-secondary",
  accent: "text-balsa-accent",
  destructive: "text-balsa-destructive",
  success: "text-balsa-success",
  warning: "text-balsa-warning",
  info: "text-balsa-info",
};
const sizeClasses: Readonly<
  Record<SpinnerSize, { ring: string[]; border: string; label: string }>
> = {
  xs: { ring: ["size-3.5"], border: "border-2", label: "text-xs" },
  sm: { ring: ["size-5"], border: "border-2", label: "text-sm" },
  md: { ring: ["size-7"], border: "border-[3px]", label: "text-sm" },
  lg: { ring: ["size-10"], border: "border-4", label: "text-base" },
  xl: { ring: ["size-14"], border: "border-[5px]", label: "text-lg" },
};
const speedClasses: Readonly<Record<SpinnerSpeed, string>> = {
  slow: "[animation-duration:1.4s]",
  normal: "[animation-duration:0.9s]",
  fast: "[animation-duration:0.55s]",
};

export function Spinner(rawProps: SpinnerProps) {
  const { props, theme } = useResolvedThemeProps("spinner", "controls", rawProps, {
    size: "md",
  } as const);
  const {
    label = "Loading",
    labelPosition = "hidden",
    color = "info",
    size,
    speed = "normal",
    theme: _themeInput,
    className,
    style,
    ...domProps
  } = props;
  void _themeInput;

  const visibleLabel = labelPosition !== "hidden";
  const classes = mergeClasses(
    "inline-flex w-fit items-center font-balsa-body",
    labelPosition === "bottom" ? "flex-col gap-balsa-xs" : "flex-row gap-balsa-sm",
    colorClasses[color],
    className,
  );
  const ringClasses = mergeClasses(
    "inline-block shrink-0 animate-spin rounded-full border-current border-r-transparent motion-reduce:animate-none",
    sizeClasses[size].ring,
    sizeClasses[size].border,
    speedClasses[speed],
  );

  return (
    <BalsaThemeContext.Provider value={theme}>
      <span
        {...domProps}
        data-balsa="spinner"
        data-theme={theme.explicitPresentation?.id}
        data-theme-base={theme.explicitPresentation?.base}
        data-color={color}
        data-size={size}
        data-speed={speed}
        data-label-position={labelPosition}
        role="status"
        aria-live="polite"
        aria-label={label}
        className={classes}
        style={
          {
            ...theme.explicitPresentation?.style,
            ...style,
          } as CSSProperties
        }
      >
        <span data-balsa="spinner-ring" className={ringClasses} aria-hidden="true" />
        {visibleLabel ? (
          <span
            className={mergeClasses(
              "font-medium text-balsa-foreground",
              sizeClasses[size].label,
            )}
            aria-hidden="true"
          >
            {label}
          </span>
        ) : null}
      </span>
    </BalsaThemeContext.Provider>
  );
}

import { extendTailwindMerge, type ClassNameValue } from "tailwind-merge";

/**
 * Every custom scale has to be declared here, not only defined in CSS.
 *
 * tailwind-merge decides which of two classes wins by knowing they belong to
 * the same group. A scale it has not been told about is not a group, so a
 * component's own `gap-balsa-md` and a caller's `gap-3` both survive the merge
 * and whichever CSS rule happens to come last decides — the caller's override
 * silently stops working. That is what happened the moment the spacing scale
 * landed, and it is invisible in the source: the class list looks right.
 */
const twMerge = extendTailwindMerge({
  extend: {
    theme: {
      radius: ["balsa-control", "balsa-surface", "balsa-panel"],
      text: [
        "balsa-2xs",
        "balsa-xs",
        "balsa-sm",
        "balsa-base",
        "balsa-prose",
        "balsa-lg",
        "balsa-xl",
        "balsa-2xl",
        "balsa-3xl",
        "balsa-4xl",
        "balsa-5xl",
        "balsa-6xl",
      ],
      leading: ["balsa-tight", "balsa-snug", "balsa-normal", "balsa-relaxed", "balsa-prose"],
      tracking: ["balsa-title", "balsa-normal", "balsa-label"],
      shadow: [
        "balsa-control",
        "balsa-surface",
        "balsa-panel",
        "balsa-sm",
        "balsa-md",
        "balsa-lg",
        "balsa-detail",
      ],
      spacing: [
        "balsa-4xs",
        "balsa-3xs",
        "balsa-2xs",
        "balsa-xs",
        "balsa-sm",
        "balsa-md",
        "balsa-lg",
        "balsa-xl",
        "balsa-2xl",
        "balsa-3xl",
        "balsa-section-sm",
        "balsa-section-md",
        "balsa-section-lg",
        "balsa-control-inline",
        "balsa-density-compact",
        "balsa-density-default",
        "balsa-density-comfortable",
      ],
    },
    classGroups: {
      // `backdrop-balsa` is a custom utility rather than a value on a scale, so
      // it has to join the group it competes with by name. Without this a
      // caller's `backdrop-blur-none` and the component's `backdrop-balsa` both
      // survive the merge and CSS order decides which blur wins — the same
      // failure the spacing scale hit the moment it landed.
      "backdrop-blur": ["backdrop-balsa", "backdrop-balsa-overlay"],
    },
  },
});

export function mergeClasses(...inputs: unknown[]): string {
  return twMerge(...(inputs as ClassNameValue[]));
}

export function withoutClassAttribute(
  attrs: Readonly<Record<string, unknown>>,
): Record<string, unknown> {
  return Object.fromEntries(
    Object.entries(attrs).filter(([name]) => name !== "class"),
  );
}

export type ActionColor = "neutral" | "primary" | "secondary" | "accent" | "destructive";
export type StatusColor = "success" | "warning" | "info";
/**
 * Status surfaces communicate state, so they exclude neutral: an action can
 * legitimately carry no emphasis, but a status that means nothing is not a status.
 */
export type SemanticColor = Exclude<ActionColor, "neutral"> | StatusColor;
export type Rounded = "none" | "sm" | "md" | "lg" | "xl" | "2xl" | "3xl" | "full";
export type CardVariant = "surface" | "elevated" | "muted" | "outline" | "soft" | "glass";
export type CardColor = ActionColor;
export type CardPadding = "none" | "sm" | "md" | "lg";
export type CardSize = Exclude<CardPadding, "none">;

interface ActionColorClassSet {
  solid: string[];
  soft: string[];
  outline: string[];
  glass: string[];
  text: string[];
}

interface SemanticColorClassSet {
  solid: string[];
  soft: string[];
  outline: string[];
  glass: string[];
}

